# RERA carpet area (sq ft), terrace (sq ft or None) and size, per unit suffix, from the brochure tables
def T(rows):
    out = {}
    for r in rows:
        no, ca, ter, size = r
        out[no] = dict(ca=ca, terrace=ter, size=size)
    return out
